log('Processing ' + papers.length + ' HM+OP candidate papers')

const results = await pipeline(
  papers,
  (p) => agent(
    `精读论文提取真实场地土壤/沉积物 HM+OP 采样点级浓度。\n\n` +
    `步骤:\n` +
    `1. Read C:\\Users\\曾鸿\\Desktop\\SRS\\outputs\\literature_mining\\_scripts\\agent_extract_prompt.md (裴总铁律规则)\n` +
    `2. Read G:\\文献整理_最终\\${p.stem}\\parsed\\paper.md 全文\n` +
    `3. 定位所有HTML表格,找"采样点级"HM+OP浓度表(行=采样点S1/A/B/点位名,列=HM元素+OP; 或转置列=采样点行=单体)\n` +
    `4. 剔除:统计行(Mean/SD/Max/Min/Median/CV/Range)/标准阈值(Grade/GB15618/GB36600/Dutch)/风险指数(HQ/TEQ/Nemerow/RI/Igeo)/盆栽spiked/水/大气/植物组织/修复效果\n` +
    `5. 提取真实采样点 HM(Cd/Pb/Cr/As/Hg/Cu/Zn/Ni,mg/kg)+OP(Sum_PAH_ngg=16EPA单体Nap/Acy/Ace/Flu/Phe/Ant/Flt/Pyr/BaA/Chr/BbF/BkF/BaP/IcdP/DahA/BghiP求和,BaP_ngg,SumPCB_ngg,SumDDT_ngg=DDT+DDE+DDD,SumHCH_ngg=α+β+γ+δ,SumPBDE_ngg,TotalPHC_mgkg; ng/g)\n` +
    `6. 输出 CSV(UTF-8-sig) 到 C:\\Users\\曾鸿\\Desktop\\SRS\\outputs\\literature_mining\\manual_extract\\hm_op\\${p.paper_id}.csv\n\n` +
    `CSV表头: paper_id,sample_id,pollutant_std,value,unit,evidence_location,matrix,site_type,province,extract_notes\n` +
    `sample_id用论文原始采样点标识(A/B/C/S1/点位名/村庄名),严禁浓度值/统计量名(Mean/Max)。单位HM=mg/kg,OP=ng/g(μg/kg=ng/g数值不变;mg/kg×1000)。extract_notes含逗号用双引号包裹。沉积物标matrix=sediment。\n\n` +
    `裴总铁律(不可违背):只用真实文献可追溯数值,禁止合成/估算;HM+OP须同论文同场地不跨论文拼;不把全省均值/风险指数/标准阈值/统计行当浓度。修复类论文重点找"修复前场地本底实测浓度"(非修复后效果/去除率/spiked实验组)。若无采样点级数据(只有统计汇总/盆栽/图),输出空CSV(仅表头)+1行notes说明。\n\n` +
    `论文: ${p.paper_id} (${p.title})。返回JSON: n_samples(提取采样点数), matrix(soil/sediment), has_hm_op(是否HM+OP真复合), skip_reason(若0说明原因)。`,
    { label: p.paper_id, schema: RESULT_SCHEMA }
  )
)

const valid = results.filter(Boolean)
const totalSamples = valid.reduce((s, r) => s + (r.n_samples || 0), 0)
const success = valid.filter(r => r.n_samples > 0)
log(`完成 ${valid.length}/${args.length} 篇, 成功 ${success.length} 篇, 新增采样点 ${totalSamples}`)
return { totalPapers: valid.length, successCount: success.length, totalNewSamples: totalSamples, successes: success, failures: valid.filter(r => r.n_samples === 0) }
